 static void setLanguage(String tag){int next=0;for(int i=0;i<TAGS.length;i++)if(TAGS[i].equals(tag))next=i;language=next;}
 static int languageIndex(){return language;}
 static String t(String source){int lang=language;if(lang==0)return source;String[] values=translations.get(source);return values==null?source:values[lang-1];}
 static String runtime(String source){String exact=t(source);if(!exact.equals(source))return exact;String prefix=null;for(String key:translations.keySet())if(key.endsWith(" ")&&source.startsWith(key)&&(prefix==null||key.length()>prefix.length()))prefix=key;return prefix==null?source:t(prefix)+source.substring(prefix.length());}
 static boolean failed(String text){return text.startsWith("Falha")||text.startsWith(t("Falha: "))||text.equals(t("Falha ao iniciar. Exporte os logs."));}
 static int entries(){return translations.size();}
